class dp3sgi_topicView extends skin_global(~id~)
{
	public $allow = 0;

	public function userInfoPane( $author, $contentid, $options )
	{		
		if( $this->allow || self::_checkAccess() )
		{		
			/* Copy current icon */

			if( $author['member_rank_img_i'] != 'pips' )
			{
				$icons = "<img src='" . $author['member_rank_img'] . "'>";		
			}	

			/* Grab all available groups... */

			foreach( ipsRegistry::cache()->getCache( 'group_cache' ) as $i )
			{
				if ( $i['g_id'] == $this->settings['guest_group'] || $i['g_id'] == $this->settings['banned_group'] )
				{
					continue;
				}

	        	$group_ids[ $i['g_id'] ] = $i['g_icon'];
			}	

			/* Get all secondary groups... */

			$this->msgrps = explode(',', $author['mgroup_others'] );

			/* Clean arrays */

			$this->msgrps = self::_cleanArray( $this->msgrps );

			if( is_array( $this->msgrps ) && count( $this->msgrps ) )
			{			
				/* Remove main group ID */

				if( in_array( $author['member_group_id'], $this->msgrps ) )
				{		
					unset( $this->msgrps[ array_search( $author['member_group_id'], $this->msgrps ) ] );
				}

				/* Play with sorting */

				self::_sort();

				/* Do we have any secondary groups? */

				if( is_array( $this->msgrps ) && count( $this->msgrps ) )
				{			
					/* Check available secondary groups... */

					foreach( $this->msgrps as $gid )
					{
						if( array_key_exists( $gid, $group_ids ) )
						{
							$tmp_icon = $group_ids[ $gid ];

							if( IPSText::mbstrlen( $tmp_icon ) )
							{
								if ( substr( $tmp_icon, 0, 4 ) != 'http' )
								{
									$tmp_icon = ipsRegistry::$settings['_original_base_url'] . '/' . $tmp_icon;
								}

								$icons .= "<br /> <img src='" . $tmp_icon . "'/>";

								unset( $tmp_icon );	
							}					
						}
					}
					/* Finally here! */

					$author['member_rank_img'] = $icons;
			        $author['member_rank_img_i'] = '';  
				}
			}			
		}

		return parent::userInfoPane( $author, $contentid, $options );
	}

	private function _cleanArray( $a = array() )
	{
		if( is_array( $a ) && count( $a ) )
		{
			foreach( $a as $ai )
			{
				if( $ai && $ai != NULL )
				{
					$ta[] = $ai;
				}
			}

			$a = $ta;
		}

		return $a;
	}

	private function _sort()
	{		
		/* INIT */

		$goodGroups = array();

		$end		= array();

		/* Get sort order */

		$order = explode(',', $this->settings['dp3_sgi_order'] );

		if( is_array( $order ) && count( $order ) )
		{ 
			$order = array_unique( $order );

			$order = self::_cleanArray( $order );

			foreach( $this->msgrps as $mid )
			{
				if( in_array( $mid, $order ) )
				{
					$goodGroups[ array_search( $mid, $order ) ] = $mid;
				}
				else
				{
					$end[] = $mid;
				}
			}

			ksort( $goodGroups );

			if( is_array( $end ) && count( $end ) )
			{
				$this->msgrps = array_merge( $goodGroups, $end );
			}
			elseif( is_array( $goodGroups ) && count( $goodGroups ) )
			{
				$this->msgrps = $goodGroups;
			}
		}
	}

	private function _checkAccess()
	{		
		/* INIT */

		$this->allow = false;

		/* Mod is enabled? */

		if( ! $this->settings['dp3_sgi_enable'] )
		{
			return false;
		}

		/* Allowed group? */

		if( ! in_array( $this->memberData['member_group_id'], explode(',', $this->settings['dp3_sgi_groups'] ) ) )
		{
			return false;
		}

		/* Still here? */

		$this->allow = true;

		return true;
	}
} // End of class

setting.conf_evalphp:
$key = 'dp3_sgi_groups';

if ( $save == 1)
{
    if ( is_array($_POST[ $key ]) )
    {
        $_POST[ $key ] = implode(",",$_POST[ $key ]);
    }
    else
    {
        $_POST[ $key ] = "";
    }
}
if ( $show == 1 )
{
    $key .= '[]';
}
